#!/usr/bin/env python3
"""TAVIZ search-result installer (company website). Run from the TAVIX 9 folder:  python3 install_taviz_seo.py .
Sets the page title to "TAVIZ | ONE TAVIZ", adds a description, share tags, site-name data for Google,
a square favicon, sitemap.xml and robots.txt. Old index.html is copied to _backup_before_taviz_seo."""
import os,sys,re,shutil,base64
ROOT=os.path.abspath(sys.argv[1] if len(sys.argv)>1 else '.')
idx=os.path.join(ROOT,'frontend','index.html')
if not os.path.exists(idx) or not os.path.exists(os.path.join(ROOT,'backend','main.py')) or not os.path.isdir(os.path.join(ROOT,'backend','company_kb')):
    sys.exit('This is not the TAVIX company website (TAVIX 9) folder. Open the right folder and try again.')
BK=os.path.join(ROOT,'_backup_before_taviz_seo'); os.makedirs(BK,exist_ok=True)
shutil.copy2(idx,os.path.join(BK,'index.html'))
FAV=''
SITE='https://tavixai.in/'
DESC='TAVIZ builds software, hardware and AI that fix real problems, and shows every project in the open. Learn to build real projects with ONE TAVIZ AI. Innovation with Honour.'
HEAD=f'''  <title>TAVIZ | ONE TAVIZ</title>
  <meta name="description" content="{DESC}" />
  <link rel="canonical" href="{SITE}" />
  <link rel="icon" type="image/png" sizes="512x512" href="/favicon.png" />
  <link rel="apple-touch-icon" href="/favicon.png" />
  <meta property="og:type" content="website" />
  <meta property="og:site_name" content="TAVIZ" />
  <meta property="og:title" content="TAVIZ | ONE TAVIZ" />
  <meta property="og:description" content="{DESC}" />
  <meta property="og:url" content="{SITE}" />
  <meta property="og:image" content="{SITE}logo.png" />
  <meta name="twitter:card" content="summary_large_image" />
  <script type="application/ld+json">{{"@context":"https://schema.org","@graph":[{{"@type":"WebSite","name":"TAVIZ","alternateName":["TAVIZ AI","ONE TAVIZ","TAVIX"],"url":"{SITE}"}},{{"@type":"Organization","name":"TAVIZ","alternateName":"TAVIZ AI","url":"{SITE}","logo":"{SITE}favicon.png","slogan":"Innovation with Honour"}}]}}</script>'''
t=open(idx,encoding='utf-8').read()
t=re.sub(r'\s*<link rel="icon"[^>]*>','',t)
t=re.sub(r'\s*<title>.*?</title>','',t,flags=re.S)
t=re.sub(r'\s*<meta (name="description"|property="og:[a-z_:]+"|name="twitter:[a-z]+")[^>]*>','',t)
t=re.sub(r'\s*<link rel="(canonical|apple-touch-icon)"[^>]*>','',t)
t=re.sub(r'\s*<script type="application/ld\+json">.*?</script>','',t,flags=re.S)
t=t.replace('</head>',HEAD+'\n</head>',1) if '<title>' not in t else t
open(idx,'w',encoding='utf-8').write(t)
pub=os.path.join(ROOT,'frontend','public'); os.makedirs(pub,exist_ok=True)
open(os.path.join(pub,'favicon.png'),'wb').write(base64.b64decode(FAV))
open(os.path.join(pub,'sitemap.xml'),'w').write('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n  <url><loc>'+SITE+'</loc></url>\n  <url><loc>'+SITE+'careers</loc></url>\n</urlset>\n')
open(os.path.join(pub,'robots.txt'),'w').write('User-agent: *\nAllow: /\nDisallow: /admin\nSitemap: '+SITE+'sitemap.xml\n')
r=open(idx,encoding='utf-8').read()
assert '<title>TAVIZ | ONE TAVIZ</title>' in r and r.count('<title>')==1 and 'name="description"' in r, 'index.html not updated'
print('Done. Title, description, favicon, sitemap.xml and robots.txt are ready. Now build and deploy.')
